// Coinzz "Carrinho Abandonado" postback (operator, 2026-10-27, grafo §134): `client.*`, `items` (an object or an array),
// `postback_name`, `checkout_url`. Only what the turn keeps leaves n8n: the phone, the name (the turn keeps the first one),
// the offer, the quantity, the price and the checkout URL — never the CPF, the e-mail or the address. What does not resolve
// goes to the operator, with those three redacted from the raw payload.
const item = $input.first().json;
const body = item.body ?? item;

const at = (obj, path) => path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
const pick = (paths) => {
  for (const p of paths) {
    const v = at(body, p);
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return undefined;
};

const items = Array.isArray(body.items) ? body.items : body.items && typeof body.items === 'object' ? [body.items] : [];
const first = items.find((i) => i && typeof i === 'object') ?? {};
const quantity = items.reduce((n, i) => n + (Number.parseInt(String(i?.quantity ?? '0'), 10) || 0), 0);
const phoneRaw = pick(['client.client_phone', 'client_phone', 'phone']);
const phone = phoneRaw === undefined ? undefined : String(phoneRaw).replace(/\D/g, '');

const cart = {
  phone,
  name: pick(['client.client_name', 'client_name']) ?? null,
  offerName: first.offer_name ?? first.product_name ?? null,
  quantity: quantity > 0 ? quantity : null,
  offerPrice: first.offer_price ?? null,
  checkoutUrl: pick(['checkout_url', 'checkoutUrl']) ?? null,
};

const missing = [];
if (!phone) missing.push('phone');

const client = body.client && typeof body.client === 'object' ? body.client : null;
const redacted = client
  ? { ...body, client: { ...client, client_document: client.client_document ? '[cpf]' : null, client_email: client.client_email ? '[e-mail]' : null, client_street: client.client_street ? '[rua]' : null, client_address_number: client.client_address_number ? '[numero]' : null, client_address_comp: client.client_address_comp ? '[complemento]' : null } }
  : body;

return [{ json: { ok: missing.length === 0, missing: missing.join(', '), cart, raw: JSON.stringify(redacted, null, 2) } }];

